let sequence=0,route='home',viewDay=today(),viewMonth=today().slice(0,7),activeItem=null,activeRecipe=null,search='',inventoryKind='all',inventoryZone='all',expiryFilter='',selectedIngredient='',filters={budget:'',time:'',exclude:''},pendingImport=null,photoDraft={product:null,expiry:null,fridge:null},attachment=null,lastStockUndo=null,recipePortions=1,photoPrefill=null,photoReview=null,photoReadController=null,photoReadRun=0,photoReadError='',photoOriginal={product:null,expiry:null,fridge:null},photoInputRun={product:0,expiry:0,fridge:0};
let viewHistory=[],registrationDraft={},lastMealResult=null,itemOrigin=null;
const pendingForms=new WeakSet();
