function rememberDraft(){const form=$('#addIngredientForm');if(!form||form.dataset.registrationCleared==='true')return;const f=new FormData(form);for(const name of ['name','quantity','expiry','opened','kind','zone','picture','mergeId'])if(f.has(name))registrationDraft[name]=String(f.get(name));registrationDraft.confirmed=f.has('confirmed');}
