 viewHistory.push({route,title:$('#trayTitle').textContent,eyebrow:$('#trayEyebrow').textContent,nodes:[...$('#trayContent').childNodes],scroll:$('#tray').scrollTop,scrolls:scrollState(),focus:document.activeElement,state:contextState(),data:JSON.stringify(J.getEnvelope())});
