 const selectedMeta=$('#selectedItemMeta');if(selectedMeta)selectedMeta.textContent=item?(item.quantity||'수량 미입력')+' · '+(item.expiry?'표시 기한 '+item.expiry:'기한 미입력'):'눌러서 수량·기한 확인';
